CREATE TABLE IF NOT EXISTS ui.masterextractattribs
(
    attribpath text COLLATE pg_catalog."default" NOT NULL,
    level character varying(255) COLLATE pg_catalog."default" NOT NULL,
    datatype character varying(255) COLLATE pg_catalog."default",
    displayname character varying(255) COLLATE pg_catalog."default",
    CONSTRAINT masterextractattribs_pkey PRIMARY KEY (attribpath, level)
);

