UPDATE ui.dashboardquery set vcdashboardquery='{
	"Account":"with recursive profile as ( SELECT * FROM masters.accounts :AttribsForm limit 50000), flat ( iaccountid, key, value) as ( select iaccountid,'''', cast(format(''{\"iaccountid\":\"%s\",\"icustomerid\":\"%s\",\"vcexternalaccountid\":\"%s\",\"iaccounttypeid\":\"%s\" ,\"vcaccount\":\"%s\" ,\"vcifsc\":\"%s\",\"vcaccountproviderid\":\"%s\",\"vcaccountname\":\"%s\",\"dtonboardingdate\":\"%s\",\"dtexpirydate\":\"%s\" ,\"bmerchant\":\"%s\",\"irecordstatus\":\"%s\",\"dtentrydatetime\":\"%s\",\"imcc\":\"%s\",\"bverified\":\"%s\"}'',cast(iaccountid as text),cast(icustomerid as text),vcexternalaccountid, cast(iaccounttypeid as text),vcaccount, vcifsc, vcaccountproviderid, vcaccountname, dtonboardingdate, dtexpirydate, cast(bmerchant as text), irecordstatus,dtentrydatetime, cast(imcc as text), cast(bverified as text)) as jsonb) as value from profile \n union select  iaccountid,concat( ''attrib.'', key), value from profile, jsonb_each(vcattribs) \n union select  iaccountid,concat(f.key, '''', j.key), j.value from flat f, jsonb_each(f.value) j where jsonb_typeof(f.value) = ''object'' ) \n select cast(json_agg(data) as text) from ( select iaccountid,jsonb_object_agg(key, value  ) as data from flat where jsonb_typeof(value)<>''object'' group by iaccountid)a;",
	"VPA": "with recursive profile as ( SELECT * FROM masters.vpa :AttribsForm limit 50000), flat ( ivpaid, key, value) as ( select ivpaid,'''', cast(format(''{\"ivpaid\":\"%s\",\"iaccountid\":\"%s\",\"vcexternaladdressid\":\"%s\",\"vcaddress\":\"%s\" ,\"iproductid\":\"%s\" ,\"vcvpaname\":\"%s\",\"bverified\":\"%s\",\"imcc\":\"%s\",\"dtonboardingdate\":\"%s\",\"dtexpirydate\":\"%s\" ,\"bmerchant\":\"%s\",\"irecordstatus\":\"%s\",\"dtentrydatetime\":\"%s\",\"ivpaproviderid\":\"%s\",\"bprofiled\":\"%s\",\"dtfirsttransaction\":\"%s\" ,\"dtlasttransaction\":\"%s\"}'', cast(ivpaid as text),cast(iaccountid as text), vcexternaladdressid,vcaddress, cast(iproductid as text), vcvpaname,cast(bverified as text), cast(imcc as text),dtonboardingdate, dtexpirydate,  cast(bmerchant as text), irecordstatus, dtentrydatetime,ivpaproviderid, cast(bprofiled as text) ,  dtfirsttransaction,dtlasttransaction) as jsonb) as value from profile \n union select  ivpaid,concat( ''attrib.'', key), value from profile, jsonb_each(vcattribs) \n union select  ivpaid,concat(f.key, '''', j.key), j.value from flat f, jsonb_each(f.value) j where jsonb_typeof(f.value) = ''object'' ) \n select cast(json_agg(data) as text) from ( select ivpaid,jsonb_object_agg(key, value  ) as data from flat where jsonb_typeof(value)<>''object'' group by ivpaid) a;",
	"Customer": "with recursive profile as ( SELECT *, icustomerid as \"custid\" FROM masters.customers :AttribsForm order by dtentrydatetime limit 50000), flat ( icustomerid, key, value) as ( select icustomerid,'''',cast(format(''{\"icustomerid\":\"%s\",\"vcexternalcustid\":\"%s\",\"vccustomertype\":\"%s\" , \"vccustomername\":\"%s\" ,\"dtonboardingdate\":\"%s\",\"irecordstatus\":\"%s\", \"dtentrydatetime\":\"%s\",\"imcc\":\"%s\", \"vcsalutation\":\"%s\", \"vcverifiedname\":\"%s\", \"vcgender\":\"%s\", \"dtdoidob\":\"%s\", \"dtonboardingdate\":\"%s\", \"vcpostalcode\":\"%s\", \"vcemail\":\"%s\", \"vcregisteredmobile\":\"%s\", \"imcc\":\"%s\", \"vcidentitytype1\":\"%s\", \"vcidentitydetails1\":\"%s\", \"vcidentitytype2\":\"%s\", \"vcidentitydetails2\":\"%s\", \"vcregisteredaddressgeolocation\":\"%s\", \"iadm3\":\"%s\", \"iadm2\":\"%s\", \"iadm1\":\"%s\", \"vccountrycode\":\"%s\", \"irecordstatus\":\"%s\", \"dtentrydatetime\":\"%s\"}'',cast(icustomerid as text),vcexternalcustid, cast(vccustomertype as text),vccustomername, dtonboardingdate, irecordstatus,dtentrydatetime, cast(imcc as text),  vcsalutation, vcverifiedname , vcgender, cast(dtdoidob as text), cast(dtonboardingdate as text), vcpostalcode, vcemail, vcregisteredmobile, cast(imcc as text), vcidentitytype1, vcidentitydetails1, vcidentitytype2, vcidentitydetails2, vcregisteredaddressgeolocation, iadm3, iadm2, iadm1, vccountrycode, irecordstatus, dtentrydatetime) as jsonb) as value from profile \n union select  icustomerid,concat( ''attrib.'', key), value from profile, jsonb_each(vcattribs) \n union select  icustomerid,concat(f.key, '''', j.key), j.value from flat f, jsonb_each(f.value) j where jsonb_typeof(f.value) = ''object'' ) \n select cast(json_agg(data) as text) from ( select icustomerid,jsonb_object_agg(key, value  ) as data from flat where jsonb_typeof(value)<>''object'' group by icustomerid)a;"
}' where idashboardqueryid = 48;

