INSERT INTO ui.masterconfig (
iconfigid, bdelete, configjson, configname) VALUES (
'4'::integer, false::boolean, '[{"description":"I want to aggregate the sum of amounts, group by account","sql":"SELECT ipayeeaccountid, CAST(MAX(dobservationamount) as NUMERIC(15,2))\nFROM transactions.trans\nWHERE (\ndttrxntime::DATE >= ''{tdate}''::DATE - INTERVAL ''45 days''\nAND\ndttrxntime::DATE <= ''{tdate}''::DATE\n)\nAND ipayeeaccountid IS NOT NULL\nGROUP BY ipayeeaccountid","tooltip":"Max/Min/Sum/Count of Amount, Grouped by Payer/Payee VPA/Account in a certain interval of days from t-date"},{"description":"I want to aggregate count of distinct addresses / accounts","sql":"SELECT ipayeeaccountid, COUNT(DISTINCT ipayervpaid) payer_gteq\nFROM transactions.trans\nWHERE (\n\ndttrxntime::DATE >= ''{tdate}''::DATE - INTERVAL ''30 days''\nAND\ndttrxntime::DATE <= ''{tdate}''::DATE\n)\nAND dobservationamount > 5000.00\nAND ipayeeaccountid IS NOT NULL\nGROUP BY ipayeeaccountid","tooltip":"Number of distinct payees/payers transacting in a day with txn value > X"},{"description":"I want to average amount for an interval","sql":"SELECT ipayeeaccountid, json_agg(json_build_object(''channel'', chan, ''avg_val'', avg_val_per_chan)) avgs\nFROM (\nSELECT ipayeeaccountid, observations->''txn''->>''class'' chan, ROUND(AVG(dobservationamount),2) avg_val_per_chan\nFROM transactions.trans\nWHERE (\ndttrxntime::DATE >= ''{tdate}''::DATE - INTERVAL ''30 days''\nAND\ndttrxntime::DATE <= ''{tdate}''::DATE\n)\nAND ipayeeaccountid IS NOT NULL\nGROUP BY ipayeeaccountid, observations->''txn''->>''class''\n) a\nGROUP BY ipayeeaccountid;","tooltip":"Avg monthly Transaction value by channel - ATM/POS/ECOMM"},{"description":"I want to aggregate count  of international txns till yesterday","sql":"SELECT ipayeeaccountid, COUNT(1) international_txn\nFROM transactions.trans\nWHERE (\ndttrxntime::DATE >= ''{tdate}''::DATE - INTERVAL ''30 days''\nAND\ndttrxntime::DATE <= ''{tdate}''::DATE\n)\nAND observations->''observations''->''geolocation''->>''country'' NOT IN (''-1'', ''IN'')\nAND ipayeeaccountid IS NOT NULL\nGROUP BY ipayeeaccountid","tooltip":"Number of International transactions in a day/month"},{"description":"I want to aggregate count of txns greater than value X","sql":"SELECT ipayeeaccountid, COUNT(1) txn_gteq\nFROM transactions.trans\nWHERE (\ndttrxntime::DATE >= ''{tdate}''::DATE - INTERVAL ''30 days''\nAND\ndttrxntime::DATE <= ''{tdate}''::DATE\n)\nAND dobservationamount > 5000.00\nAND ipayeeaccountid IS NOT NULL\nGROUP BY ipayeeaccountid","tooltip":"Number of transactions greater than a threshold in a day/month"}]'::jsonb, 'Historic Profile Sql Templates'::character varying)
 returning iconfigid;